def payload_files():
 blob=base64.b85decode(PAYLOAD)
 if hashlib.sha256(blob).hexdigest()!=PAYLOAD_SHA256:raise ValueError('Payload hash mismatch')
 result={}
 with tarfile.open(fileobj=io.BytesIO(gzip.decompress(blob)),mode='r:') as tar:
  members=tar.getmembers()
  if len(members)!=len(SOURCE_MANIFEST) or {m.name for m in members}!=set(SOURCE_MANIFEST):raise ValueError('Payload membership mismatch')
  for m in members:
   p=Path(m.name)
   if not m.isfile() or p.is_absolute() or '..' in p.parts or m.name in result:raise ValueError('Unsafe payload path')
   data=tar.extractfile(m).read()
   if hashlib.sha256(data).hexdigest()!=SOURCE_MANIFEST[m.name]:raise ValueError('Source hash mismatch')
   result[m.name]=data
 return result

def embedded_guards():
 m=types.ModuleType('_sequential_embedded_paths');exec(compile(payload_files()['tools/path_guards.py'],'<hash-verified-path-guards>','exec'),m.__dict__);return m

def unpack(destination):
 guards=embedded_guards();destination=guards.no_symlink_ancestors(destination);files=payload_files()
 # Preflight the whole extraction BEFORE the first mutation, including existing
 # nested ancestors and stale/mismatched files; no symlink bypass via resolve().
 if destination.exists():
  if not destination.is_dir():raise ValueError('Extraction root is not a directory')
  guards.reject_tree_symlinks(destination)
 for name,data in files.items():
  target=guards.no_symlink_ancestors(destination/name)
  if not target.is_relative_to(destination):raise ValueError('Extraction target escapes source')
  if target.exists() and (not target.is_file() or hashlib.sha256(target.read_bytes()).hexdigest()!=SOURCE_MANIFEST[name]):raise ValueError('Refusing modified extracted source')
 destination.mkdir(parents=True,exist_ok=True)
 for name,data in files.items():
  target=destination/name;target.parent.mkdir(parents=True,exist_ok=True)
  if not target.exists():target.write_bytes(data)
 return destination

def load_module(path,name):
 spec=importlib.util.spec_from_file_location(name,path);m=importlib.util.module_from_spec(spec);sys.modules[name]=m;spec.loader.exec_module(m);return m

def main():
 started=time.monotonic()
 if sys.flags.optimize:raise RuntimeError('Proof launcher requires assertions enabled')
 p=argparse.ArgumentParser(description=__doc__)
 mode=p.add_mutually_exclusive_group();mode.add_argument('--plan',action='store_true');mode.add_argument('--self-test',action='store_true');mode.add_argument('--prepare',action='store_true');mode.add_argument('--execute-browser',action='store_true');mode.add_argument('--extract-only',action='store_true');mode.add_argument('--validate-report',type=Path);mode.add_argument('--validate-public-build',type=Path);mode.add_argument('--render-report',type=Path)
 p.add_argument('--cache',type=Path,default=Path('scheduler-sequential-cache'));p.add_argument('--private',type=Path,default=Path('scheduler-sequential-output'));p.add_argument('--build-proof',type=Path);p.add_argument('--html-output',type=Path);p.add_argument('--ci-start-monotonic',type=float);a=p.parse_args()
 guards=embedded_guards();private=guards.no_symlink_ancestors(a.private);cache=guards.no_symlink_ancestors(a.cache);source=private/('source-'+PAYLOAD_SHA256[:12]);work=cache/('build-'+PAYLOAD_SHA256[:12])
 guards.require_disjoint(private,cache);guards.validate_mutable_targets(private,source,('browser','public-build.json','report.html'));guards.preflight_cache(work,source)
 # Never overwrite the standalone source itself through an output alias.
 launcher=guards.no_symlink_ancestors(Path(__file__).absolute())
 for target in (private/'browser',private/'public-build.json',private/'report.html',work):
  if launcher==target or launcher.is_relative_to(target):raise ValueError('Mutable target overlaps standalone source')
 if a.html_output is not None:
  target=guards.no_symlink_ancestors(a.html_output)
  if target.is_relative_to(source) or target==launcher:raise ValueError('HTML output overlaps immutable source')
 if a.prepare or a.execute_browser:
  # All guards above precede stale-file deletion, including private/browser.
  for rel in ('public-build.json','browser/browser-report.json','report.html'):
   guards.check_targets(private,(rel,));(private/rel).unlink(missing_ok=True)
 origin=started if a.ci_start_monotonic is None else a.ci_start_monotonic
 if type(origin) not in (int,float) or not math.isfinite(origin) or not 0<=origin<=started:raise ValueError('Invalid or future monotonic origin')
 if (a.prepare or a.execute_browser) and started-origin>2700:raise ValueError('Pre-browser 45-minute eligibility exceeded')
 root=unpack(source);env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1',SCHEDULER_CORE_LAUNCHER_PATH=str(launcher))
 owner=load_module(root/'tools/process_guard.py','_sequential_launcher_owner')
 def run(*args,browser=False):
  command=[sys.executable,*map(str,args)]
  if a.prepare or a.execute_browser:
   limit=origin+9000 if browser else origin+2700
   if time.monotonic()>=limit:raise ValueError('Fixed phase deadline reached before dispatch')
   owner.run_owned(command,cwd=root,env=env,deadline=limit,cleanup_deadline=origin+9000)
  else:subprocess.run(command,cwd=root,env=env,check=True)
 if a.extract_only:print(json.dumps(dict(payload_sha256=PAYLOAD_SHA256,files=len(SOURCE_MANIFEST),prepared_only=True)));return
 if a.render_report:
  if a.html_output is None:raise ValueError('--html-output required')
  extra=['--build-proof',a.build_proof.absolute()] if a.build_proof else [];run('tools/render_report.py','--report',a.render_report.absolute(),'--output',a.html_output.absolute(),*extra);return
 if a.validate_report:run('browser/browser.py','--validate-report',a.validate_report.absolute());return
 if a.validate_public_build:run('tools/public_build_receipt.py','--validate',a.validate_public_build.absolute());return
 run('tools/bootstrap.py','--verify-vendor')
 if a.self_test:
  for folder in ('tools','workflow','browser/tests','tests'):run('-m','unittest','discover','-s',folder,'-p','test_*.py','-v')
 if not (a.prepare or a.execute_browser):run('tools/bootstrap.py','--plan');run('browser/browser.py','--plan');return
 paths=work/'toolchain-paths.json'
 run('tools/bootstrap.py','--work',work,'--prepare-fixtures')
 run('tests/run_native.py','--paths',paths,'--output',work/'native-tests')
 run('tools/build.py','--paths',paths,'--work',work)
 run('tools/public_build_receipt.py','--manifest',work/'build.json','--output',private/'public-build.json','--require-linked')
 run('browser/browser.py','--manifest',work/'build.json','--verify-inputs')
 if a.execute_browser:
  if time.monotonic()-origin>2700:raise ValueError('Pre-browser 45-minute eligibility exceeded')
  run('browser/browser.py','--manifest',work/'build.json','--private',private/'browser','--execute','--preflight-start-monotonic',origin,'--preflight-origin','standalone_launcher' if a.ci_start_monotonic is None else 'ci_first_step',browser=True)
if __name__=='__main__':main()
